"""Delivery of one payload to one target."""


class TargetBusy(Exception):
    """The target had no free slot for this payload."""


def deliver(target, payload):
    slot = target.acquire_slot()
    if slot is None:
        raise TargetBusy(target.name)
    return slot.submit(payload)

