"""`relay send TARGET FILE`: deliver one payload from the command line."""
import time

from relay.transport import TargetBusy, deliver

RETRY_DELAYS = (0.5, 1.0, 2.0)


def send(target, payload):
    for delay in RETRY_DELAYS:
        try:
            return deliver(target, payload)
        except TargetBusy:
            time.sleep(delay)
    return deliver(target, payload)

