"""`relay batch FILE`: run the steps of a batch file in order."""
from relay.transport import deliver


def run_step(step):
    return deliver(step.target, step.payload)


def run_with_retry(step):
    attempts = 1 + step.retry
    for attempt in range(attempts):
        try:
            return run_step(step)
        except Exception:
            if attempt == attempts - 1:
                raise


def run_batch(steps):
    for step in steps:
        run_with_retry(step)

