"""Per-key request counters, kept in memory."""


class Counters:
    def __init__(self):
        self._counts = {}

    @classmethod
    def load(cls):
        return cls()

    def hit(self, key):
        self._counts[key] = self._counts.get(key, 0) + 1
        return self._counts[key]

    def reset_all(self):
        self._counts.clear()

