from relay.transport import deliver


class InputRequired(Exception):
    """A step asked for interactive input; batch never reads stdin."""


def run_step(step):
    if step.prompt is not None:
        raise InputRequired(step.name)
    return deliver(step.target, step.payload)


def run_batch(steps):
    for step in steps:
        run_step(step)

