"""`relay batch FILE`: run the steps of a batch file in order."""
from relay.transport import deliver


class StepResult:
    def __init__(self, step, ok, error=None):
        self.step, self.ok, self.error = step, ok, error


def run_step(step):
    try:
        deliver(step.target, step.payload)
        return StepResult(step, True)
    except Exception as error:
        return StepResult(step, False, error)


def run_batch(steps):
    results = []
    for step in steps:
        result = run_step(step)
        results.append(result)
        if not result.ok:
            break
    return results
